    for vault in self._vaults:
        if id(vault) in seen:
            continue
        seen.add(id(vault))
        try:
            vault.close()
            vault.close()  # repeated release must stay an error-free no-op
        except BaseException as exc:
            if handle_error is None:
                handle_error = exc

