        self._tmp.cleanup()
    except OSError as exc:
        removal_error = exc
        for base, dirs, files in os.walk(self.tmp_path, topdown=False):
            for entry in files + dirs:
                try:
                    os.chmod(os.path.join(base, entry), 0o700)
                except OSError:
                    pass
